module mis_finder(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [3:0] n,\n    input wire [4:0] m,\n    input wire [191:0] edges_packed,\n    output reg [3:0] result,\n    output reg done\n);\n    // State declarations\n    localparam [2:0] IDLE = 3'd0;\n    localparam [2:0] CHECK = 3'd1;\n    localparam [2:0] UPDATE = 3'd2;\n    localparam [2:0] NEXT = 3'd3;\n    localparam [2:0] DONE_STATE = 3'd4;\n    \n    // Internal registers\n    reg [2:0] state;\n    reg [7:0] subset;\n    reg [3:0] max_size;\n    reg [7:0] max_subset_reg;\n    \n    // Edge unpacking\n    wire [7:0] edges [0:23];\n    genvar i;\n    generate\n        for (i = 0; i < 24; i = i + 1) begin : unpack\n            assign edges[i] = edges_packed[i*8 +: 8];\n        end\n    endgenerate\n    \n    // Max subset calculation (combinational)\n    always @(*) begin\n        case (n)\n            4'd1: max_subset_reg = 8'b00000001;\n            4'd2: max_subset_reg = 8'b00000011;\n            4'd3: max_subset_reg = 8'b00000111;\n            4'd4: max_subset_reg = 8'b00001111;\n            4'd5: max_subset_reg = 8'b00011111;\n            4'd6: max_subset_reg = 8'b00111111;\n            4'd7: max_subset_reg = 8'b01111111;\n            4'd8: max_subset_reg = 8'b11111111;\n            default: max_subset_reg = 8'b0;\n        endcase\n    end\n    \n    // Validity checking (combinational)\n    wire [23:0] edge_valid_flags;\n    generate\n        for (i = 0; i < 24; i = i + 1) begin : validity_gen\n            assign edge_valid_flags[i] = (i < m) ? ~(subset[edges[i][7:4]] & subset[edges[i][3:0]]) : 1'b1;\n        end\n    endgenerate\n    wire is_valid = &edge_valid_flags;\n    \n    // Popcount (combinational size calculation)\n    wire [3:0] subset_size;\n    assign subset_size = subset[0] + subset[1] + subset[2] + subset[3] + subset[4] + subset[5] + subset[6] + subset[7];\n    \n    // State machine\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            subset <= 8'd0;\n            max_size <= 4'd0;\n            result <= 4'd0;\n            done <= 1'b0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        subset <= 8'd0;\n                        max_size <= 4'd0;\n                        state <= CHECK;\n                    end\n                end\n                \n                CHECK: begin\n                    state <= UPDATE;\n                end\n                \n                UPDATE: begin\n                    if (is_valid && (subset_size > max_size)) begin\n                        max_size <= subset_size;\n                    end\n                    state <= NEXT;\n                end\n                \n                NEXT: begin\n                    if (subset < max_subset_reg) begin\n                        subset <= subset + 8'd1;\n                        state <= CHECK;\n                    end else begin\n                        result <= max_size;\n                        done <= 1'b1;\n                        state <= DONE_STATE;\n                    end\n                end\n                \n                DONE_STATE: begin\n                    // Maintain done signal\n                    state <= DONE_STATE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule